--[DBO]--
-- CREAZIONE TABELLA geo_city --
IF NOT EXISTS(select * from sysobjects where id = object_id(N'[dbo].[geo_city]') and OBJECTPROPERTY(id, N'IsUserTable') = 1)
BEGIN
CREATE TABLE [dbo].[geo_city] (
idcity int NOT NULL,
idcountry int NULL,
lt datetime NULL,
lu varchar(64) NULL,
newcity int NULL,
oldcity int NULL,
start date NULL,
stop date NULL,
title varchar(65) NULL,
 CONSTRAINT xpkgeo_city PRIMARY KEY (idcity
)
)
END
GO

-- VERIFICA STRUTTURA geo_city --
IF NOT exists(select * from [sysobjects] as T inner join syscolumns C on T.ID = C.ID where t.name = 'geo_city' and C.name = 'idcity' AND (T.uid = USER_ID( ) OR T.uid = USER_ID('dbo')))
BEGIN
	ALTER TABLE [geo_city] ADD idcity int NOT NULL DEFAULT 0
	declare @vincolo varchar(100)
	select @vincolo = object_name(const.constid) from syscolumns col join sysconstraints const on const.id = col.id and const.colid = col.colid where col.id = object_id('geo_city') and col.name = 'idcity' and objectproperty(const.constid, 'IsDefaultCnst')=1
	exec ('ALTER TABLE [geo_city] drop constraint '+@vincolo)
END
GO

